const source = `function verify109(log) {
 const cols="ABCDEFGHJ", p=s=>s==="pass"?null:(9-Number(s.slice(1)))*9+cols.indexOf(s[0]), pt=i=>cols[i%9]+(9-Math.floor(i/9));
 const adj=i=>[i%9?i-1:-1,i%9<8?i+1:-1,i>=9?i-9:-1,i<72?i+9:-1].filter(x=>x>=0);
 const parse=r=>{const t=r.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n"),b=Array(81).fill(".");let rows=0;for(const l of t.split("\\n")){const m=l.match(/^\\s*([1-9])\\s+((?:[XO.]\\s+){8}[XO.])\\s+[1-9]\\s*$/);if(m){rows++;m[2].trim().split(/\\s+/).forEach((v,x)=>b[(9-Number(m[1]))*9+x]=v);}}if(rows!==9)throw Error("Missing board rows");const cap=t.match(/Captured by Black: (\\d+); by White: (\\d+)/),next=t.match(/Move number: (\\d+)/),ko=t.match(/Ko point: (\\w+)/);return {text:t,board:b,captures:{B:+cap[1],W:+cap[2]},next:+next[1],ko:ko[1]};};
 const group=(b,i)=>{const c=b[i],stack=[i],seen=new Set([i]),libs=new Set();while(stack.length){const j=stack.pop();for(const k of adj(j)){if(b[k]===".")libs.add(k);else if(b[k]===c&&!seen.has(k)){seen.add(k);stack.push(k);}}}return {stones:[...seen],libs:[...libs]};};
 let b=Array(81).fill("."),captures={B:0,W:0},ko=null,moves=[],events=[],checks=[],positions=[];
 const play=(color,move)=>{const i=p(move),c=color==="B"?"X":"O",enemy=c==="X"?"O":"X";if(i===null){ko=null;moves.push({number:moves.length+1,color,move});return;}if(i<0||i>=81||b[i]!=="."||i===ko)throw Error("Illegal actual move "+move);b[i]=c;let taken=[];for(const j of adj(i)){if(b[j]===enemy){const g=group(b,j);if(g.libs.length===0){taken.push(...g.stones);g.stones.forEach(k=>b[k]=".");}}}const own=group(b,i);if(own.libs.length===0)throw Error("Actual suicide "+move);captures[color]+=taken.length;ko=taken.length===1&&own.stones.length===1&&own.libs.length===1?taken[0]:null;moves.push({number:moves.length+1,color,move});if(taken.length)events.push({number:moves.length,color,move,captured:taken.map(pt).sort()});};
