 const displayed=inspect(b),dead=["D8","E8","F8"],scoredBoard=b.slice();dead.forEach(s=>{if(scoredBoard[p(s)]!=="X")throw Error("Dead inventory mismatch");scoredBoard[p(s)]=".";});const inferredScore=inspect(scoredBoard),target=[];for(let row=1;row<=5;row++)for(const col of cols){const s=col+row;if(s!=="D5")target.push(s);}const owned=new Set(inferredScore.groups.filter(x=>x.color==="X").flatMap(x=>x.stones).concat(inferredScore.exclusive.B)),retained=target.filter(s=>owned.has(s)).sort(),lost=target.filter(s=>!owned.has(s)).sort(),gained=[...owned].filter(s=>!target.includes(s)).sort();
 const sgf="(;GM[1]FF[4]CA[UTF-8]SZ[9]RU[Chinese]KM[7]PB[Codex]PW[KataGo 20k human-style]DT[2026-10-06]RE[W+18]"+moves.map(m=>";"+m.color+"["+(m.move==="pass"?"":String.fromCharCode(97+cols.indexOf(m.move[0]))+String.fromCharCode(97+9-Number(m.move.slice(1))))+"]").join("")+")\\n";
